import"./chunk-7CGTOI24.js";var e={slug:"jogos-vorazes-amanhecer-na-colheita-estreia",title:"Jogos Vorazes: Amanhecer na Colheita estreia dia 19. O que saber antes",dek:"A adapta\xE7\xE3o do livro de Suzanne Collins sobre o jovem Haymitch chega aos cinemas brasileiros em 19 de novembro. Elenco, dire\xE7\xE3o e o que muda em Panem.",section:"filmes",kind:"noticia",tags:["Jogos Vorazes","Estreias","Adapta\xE7\xE3o"],date:"2026-11-08",hero:{ref:"movie:1300968",pick:0,alt:"Cena de Jogos Vorazes: Amanhecer na Colheita"},body:[{p:"Panem est\xE1 de volta. *Jogos Vorazes: Amanhecer na Colheita* estreia no Brasil na quinta-feira, **19 de novembro**, um dia depois da estreia mundial, e adapta o livro de Suzanne Collins publicado em 2025."},{ficha:"movie:1300968"},{h2:"Do que se trata"},{p:"A hist\xF3ria se passa 24 anos antes de *Jogos Vorazes* e come\xE7a na manh\xE3 da colheita da 50\xAA edi\xE7\xE3o dos jogos, o Segundo Massacre Quatern\xE1rio. Nessa edi\xE7\xE3o especial, cada distrito envia o dobro de tributos, dois garotos e duas garotas, totalizando 48 participantes."},{p:"No centro est\xE1 **Haymitch Abernathy**, aos 16 anos. O personagem que o p\xFAblico conheceu como o mentor amargo de Katniss e Peeta, vivido por Woody Harrelson nos filmes originais, ganha aqui a sua pr\xF3pria trag\xE9dia."},{h2:"Quem est\xE1 no elenco"},{p:"Joseph Zada interpreta Haymitch. Mckenna Grace vive Maysilee Donner, Whitney Peak \xE9 Lenore Dove Baird, e Ralph Fiennes assume o Presidente Coriolanus Snow. Jesse Plemons aparece como Plutarch Heavensbee e Glenn Close como Drusilla Sickle, segundo os cr\xE9ditos do TMDB."},{img:"movie:1300968",pick:1,caption:"O filme tem 158 minutos e classifica\xE7\xE3o indicativa de 16 anos. Imagem de divulga\xE7\xE3o."},{h2:"Francis Lawrence de volta"},{p:"A dire\xE7\xE3o \xE9 de Francis Lawrence, que j\xE1 comandou *Em Chamas*, as duas partes de *A Esperan\xE7a* e *A Cantiga dos P\xE1ssaros e das Serpentes*. O roteiro \xE9 de Billy Ray e Michael Lesslie, e a produ\xE7\xE3o, da Lionsgate com a Color Force."},{quote:"Haymitch sempre foi o personagem que sabia mais do que dizia. O filme tem a chance de mostrar o pre\xE7o desse sil\xEAncio."},{h2:"Precisa rever os outros antes?"},{p:"N\xE3o \xE9 obrigat\xF3rio. *Amanhecer na Colheita* funciona sozinho, mas ganha camadas para quem lembra do Haymitch adulto e da ascens\xE3o de Snow em *A Cantiga dos P\xE1ssaros e das Serpentes*. Se tiver tempo para s\xF3 um filme, reveja *Em Chamas*, que tamb\xE9m se passa em um Massacre Quatern\xE1rio."},{box:"Esta \xE9 uma mat\xE9ria de servi\xE7o, escrita antes da estreia. A reda\xE7\xE3o ainda n\xE3o assistiu ao filme.",title:"Antes da sess\xE3o"},{p:"Confira as outras [estreias de novembro nos cinemas](/artigo/estreias-de-novembro-nos-cinemas)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{1300968:{id:1300968,title:"Jogos Vorazes: Amanhecer na Colheita",original:"The Hunger Games: Sunrise on the Reaping",overview:"Revisite o mundo de Panem 24 anos antes dos eventos de Jogos Vorazes, come\xE7ando na manh\xE3 da colheita dos 50\xBA Jogos Vorazes, tamb\xE9m conhecida como o Segundo Massacre Quatern\xE1rio.",poster:"/ibZ6GSHtCeC7fLDJ2uyXNemgYwr.jpg",backdrops:["/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg","/cCGTwo2qtzKcvXvFvkvXO4J2f2D.jpg","/6bM4RwgUsL8hPz5FjFDKM0vrDu2.jpg","/9B3AMSs7A3bqqFLKlOv6W4LyAHG.jpg","/497KYpXqaxh99RPMVmsxAg76Nal.jpg"],runtime:158,genres:["Fic\xE7\xE3o cient\xEDfica","A\xE7\xE3o","Aventura"],cert:"16",release:"2026-11-19",world:"2026-11-18",directors:["Francis Lawrence"],writers:["Billy Ray","Michael Lesslie"],cast:[{name:"Joseph Zada",role:"Haymitch Abernathy"},{name:"Mckenna Grace",role:"Maysilee Donner / Merrilee Donner"},{name:"Ralph Fiennes",role:"President Coriolanus Snow"},{name:"Jesse Plemons",role:"Plutarch Heavensbee"},{name:"Glenn Close",role:"Drusilla Sickle"},{name:"Whitney Peak",role:"Lenore Dove Baird"}],studios:["Lionsgate","Color Force"],country:"US"}},tv:{}};export{o as media,e as post};
